  v = `Opcional: Puedes elegir invitar a otros desarrolladores para incluir sus juegos en tu lote. Como dueño del lote, es tu responsabilidad coordinar con los otros desarrolladores. También, como dueño, eres el único que puede publicar el lote en la tienda de Steam. Los grupos invitados pueden elegir los juegos/paquetes que se incluirán. Cada vez que un paquete se agregue al lote, o cambie el porcentaje de descuento, todos los colaboradores deberán aprobar la inclusión de su juego en el paquete antes de poderlo publicar.`,
