  Vj = `La fecha de publicación más temprana posible es dos semanas después de que la página de la tienda se haga visible como "Próximamente" o 21 días después de la primera compra de un crédito de aplicación (lo que ocurra más tarde). Tenlo en cuenta al planificar.`,
  Hj = `La fecha de publicación más temprana posible es dos semanas después de que la página de la tienda se haga visible como "Próximamente". Tenlo en cuenta al planificar.`,
  Uj = `Selecciona la fecha en la que tienes previsto lanzar tu aplicación en Steam. Si aún falta mucho tiempo para el lanzamiento, introduce la fecha más aproximada que puedas. Si necesitas retrasar el lanzamiento, tendrás que actualizar la fecha aquí con al menos dos semanas de antelación a la fecha especificada anteriormente.`,
