  Kj = `Tu fecha de lanzamiento prevista se ha establecido para el %1$s. Si necesitas modificar esta fecha, <1>ponte en contacto con Valve desde aquí</1> con el motivo de tu nueva fecha de lanzamiento e indica qué fecha prefieres. Debes estar muy seguro de que el lanzamiento tendrá lugar en esta nueva fecha.`,
