  CM = `Tu juego base y demo tienen diferentes tipos de restricciones de país. Ambos deben estar configurados en una lista de permitidos o denegados, no en una de cada una. Juego base: %1$s. Demo: %2$s.`,
  wM = `Tu juego base y demo tienen diferentes restricciones de país. Los correos electrónicos de la lista de deseados solo se enviarán a los clientes que puedan acceder a ambos. Juego base: %1$s. Demo: %2$s.`,
  TM = `solo en %1$s`,
