  DM = `sin restricciones`,
  OM = `Atención, tu demo aún no aparece en la tienda.`,
  kM = `Asocia la demo con tu juego base en <1>"Editar página de la tienda > pestaña Configuraciones especiales > Demos asociadas"</1> y asegúrate de publicar los cambios. Una vez completados estos pasos, es posible que la actualización tarde unos minutos en aparecer.`,
  AM = `¿Quieres avisar por correo electrónico del lanzamiento de la demo a quienes tienen tu juego en su lista de deseados?`,
  jM = `¿Quieres avisar por correo electrónico del lanzamiento de la demo a las 3403 personas que tienen tu juego en su lista de deseados?`,
  MM = `Limitaciones importantes`,
  NM = `<1><2>Solo se puede enviar un correo electrónico para avisar del lanzamiento de la demo.</2> Aunque desactives y vuelvas a activar la demo en el futuro, solo podrás enviar notificaciones por correo electrónico una vez.</1><1><2>Cada jugador recibirá solo un correo electrónico de Steam en un período de dos semanas.</2> Si lanzas el juego completo antes de que transcurran dos semanas tras enviar este correo, Steam no avisará por correo electrónico a ninguna de las personas a las que se notifique ahora. Ten esto en cuenta para trazar tus planes.</1>`,
