  gN = `Para ayudar a los jugadores a encontrar juegos que cumplan con sus necesidades de accesibilidad, responde a algunas preguntas sobre funciones de accesibilidad en tu juego.`,
  _N = `De acuerdo con lo que nos dijiste sobre las funciones de accesibilidad que ofrece tu juego, Steam mostrará la siguiente lista desplegable a los clientes:`,
  vN = `Según lo que nos has contado, tu juego no tiene ninguna de las funciones de accesibilidad compatibles con Steam.`,
  yN = `Asistente de funciones de accesibilidad`,
  bN = `Jugabilidad`,
  xN = `Para obtener detalles sobre las funciones de accesibilidad del juego, consulta la <1>Documentación sobre funciones de accesibilidad de Steamworks</1>.`,
  SN = `¿Cuáles de estas funciones de accesibilidad en la jugabilidad ofrece tu juego?`,
  CN = `Dificultad ajustable`,
  wN = `Los ajustes de dificultad permiten a los jugadores adaptar su experiencia a sus habilidades y preferencias.`,
  TN = `Guardar en cualquier momento`,
  EN = `Los jugadores pueden guardar partidas tanto de forma automática como manual, y pueden hacerlo en cualquier momento del juego. Los jugadores pueden buscar esta etiqueta para saber que no perderán progresos significativos.`,
  DN = `Menús de juegos narrados`,
  ON = `Los jugadores pueden escuchar los menús del juego con narración en audio.`,
  kN = `Los jugadores con limitaciones de visión pueden depender de la narración para interactuar con los menús. Si tu juego tiene menús de juego narrados, o bien has expuesto tu árbol de interfaz de usuario a lectores de pantalla (por ejemplo, a través de <1>Microsoft UI Automation</1>) o bien has proporcionado narración para todos los menús y notificaciones del juego. Para obtener recomendaciones, consulta la <2>Documentación sobre funciones de accesibilidad de Steamworks</2>.`,
  AN = `¿Tu juego tiene menús narrados?`,
  jN = `Sí, los jugadores pueden recurrir a la narración para navegar por los menús del juego.`,
  MN = `No, mi juego no tiene menús del juego narrados.`,
  NN = `Jugable sin visión`,
  PN = `Los jugadores pueden jugar el juego completo sin ver la pantalla. O tu juego se diseñó pensando en una jugabilidad que no requiere visión (por ejemplo, basándose en sonidos) o su compatibilidad con lectores de pantalla y narración es lo suficientemente buena como para disfrutar del juego completo.`,
  FN = `Algunos juegos pueden jugarse sin ver la pantalla. Por ejemplo, un juego puede estar basado completamente en sonidos, o su compatibilidad con lectores de pantalla y narración es lo suficientemente buena como para ofrecer una experiencia completa sin visión.`,
  IN = `¿Se puede jugar tu juego sin visión?`,
  LN = `Sí, los jugadores pueden jugarlo sin ver la pantalla.`,
  RN = `No, mi juego no se puede jugar sin visión.`,
  zN = `Controles de volumen personalizados`,
  BN = `El volumen para diferentes tipos de audio en el juego se puede ajustar independientemente .`,
  VN = `Es posible que los jugadores necesiten reducir los sonidos que les distraen para poder concentrarse en los que necesitan oír. Si tu juego tiene controles de volumen personalizados, los jugadores pueden ajustar los niveles relativos de los distintos tipos de sonido, como la música, los efectos de sonido, el audio ambiental y el habla de los personajes. Un único control deslizante de volumen no cumple este criterio. Para obtener recomendaciones, consulta la <1>Documentación sobre funciones de accesibilidad de Steamworks</1>.`,
  HN = `¿Tu juego tiene controles de volumen personalizados?`,
  UN = `Sí, los jugadores pueden ajustar el volumen relativo de diferentes tipos de sonidos en mi juego.`,
  WN = `No, mi juego no tiene controles de volumen personalizados.`,
  GN = `Audio direccional`,
  KN = `Los jugadores pueden tener que recurrir a señales de audio para comprender la ubicación de los objetos del juego. Si tu juego tiene sonido estéreo, este transmite la posición relativa de un sonido por los canales izquierdo y derecho. Si tu juego tiene sonido envolvente, los jugadores pueden saber de dónde proviene un sonido en cualquier dirección, incluyendo arriba, abajo, detrás y delante.`,
  qN = `¿Con qué tipo de audio direccional es compatible tu juego?`,
  JN = `Sonido envolvente: audio direccional (p. ej., 3.1, 5.1, 7.1 o tecnologías similares)`,
  YN = `Sonido estéreo: canales izquierdo y derecho`,
  XN = `Mi juego no tiene audio direccional`,
  ZN = `Sonido estéreo`,
  QN = `Los jugadores pueden identificar de cuán lejos a la izquierda o derecha vienen los sonidos.`,
  $N = `Sonido envolvente`,
  eP = `Los jugadores pueden identificar de cuán lejos vienen los sonidos en cualquier dirección.`,
  tP = `Visión`,
  nP = `Selecciona con cuáles de las siguientes funciones de accesibilidad visual es compatible tu juego. Para obtener más información sobre las funciones de accesibilidad visuales, consulta la <1>Documentación sobre funciones de accesibilidad de Steamworks</1>.`,
  rP = `¿Cuáles de estas funciones de accesibilidad visual ofrece tu juego?`,
  iP = `Tamaño del texto ajustable`,
  aP = `Los jugadores pueden ajustar el tamaño del texto del juego, los menús, los cuadros de diálogo de los personajes o los subtítulos.`,
  oP = `Opciones de subtítulos`,
  sP = `Los jugadores tienen opciones para personalizar la visualización de subtítulos para todo el contenido hablado y la información de audio esencial. Los subtítulos básicos pueden resultar insuficientes para los jugadores con problemas de visión. Ofrecer opciones de opacidad de fondo, color y tamaño del texto puede permitir a los jugadores personalizar los subtítulos para su comodidad.`,
  cP = `Alternativas de color`,
  lP = `La jugabilidad no depende de los colores para comunicar información importante o los jugadores tienen la opción de ajustar los colores utilizados para distinguir la información.`,
  uP = `Comodidad de la cámara`,
  dP = `Los jugadores tienen la opción de ajustar o desactivar los movimientos incómodos de la cámara, como temblores de la pantalla, el balanceo de la cámara o el desenfoque de movimiento, o tu juego no presenta estos efectos.`,
  fP = `Controles de contraste`,
  pP = `El contraste se puede ajustar, por ejemplo, cambiando los colores de primer plano y de fondo, resaltando los elementos de primer plano o activando los modos oscuro o claro.`,
  mP = `Control`,
  hP = `Algunos jugadores tienen herramientas de accesibilidad que se asignan a entradas de teclado, mouse o táctiles, o los jugadores pueden preferir usar esas entradas. Para obtener información sobre las funciones de accesibilidad de entrada, consulta las <1>Documentación sobre funciones de accesibilidad de Steamworks</1>.`,
  gP = `¿Cuáles de estos modos de entrada son compatibles con tu juego?`,
