  CP = `Entradas temporizadas`,
  wP = `Algunos jugadores no podrían realizar entradas con cualquier sincronización. Para otros, las secuencias de entradas cronometradas con precisión ("eventos de acción rápida") o de presionar botones repetidamente pueden resultar incómodas o imposibles. Algunos juegos, como las novelas visuales o los juegos por turnos, no requieren ninguna sincronización de entradas.`,
