  kP = `Jugable sin eventos de acción rápida`,
  AP = `Los jugadores pueden evitar secuencias de entradas cronometradas con precisión ("eventos de acción rápida") o de presionar repetidamente los botones.`,
  jP = `Jugable a tu propio ritmo`,
  MP = `Los jugadores pueden tomar todo el tiempo que necesiten para cada entrada o las entradas con restricciones de tiempo se pueden desactivar u omitir.`,
  NP = `Conversión de texto a voz y de voz a texto`,
  PP = `Las experiencias sociales como el chat de texto o el chat de voz del juego, pueden no estar disponibles para los jugadores con problemas de visión o audición. La conversión de texto a voz permite a los jugadores escuchar el chat de texto en tiempo real, mientras que la conversión de voz a texto permite a los jugadores leer el chat de voz en tiempo real. Para ver recomendaciones sobre las funciones de conversión de texto a voz y de voz a texto, consulta la <1>documentación sobre funciones de accesibilidad de Steamworks</1>.`,
