  OI = `Paso %1$s`,
  kI = `Compatibilidad con ENTRADA GENERAL`,
  AI = `Para describir mejor el nivel de compatibilidad del control del juego a los jugadores, tenemos un asistente rápido con unas cuantas preguntas breves. Responde a las preguntas del asistente lo mejor que puedas para que Steam pueda conectar a los jugadores con juegos que funcionan bien con los dispositivos que tienen.`,
  jI = `Ten en cuenta que todos los dispositivos de realidad virtual, incluidos los dispositivos de entrada, compatibles con tu juego deben describirse en los requisitos del sistema. La compatibilidad con el controlador en esta sección se refiere al modo de escritorio del juego y al modo Big Picture.`,
