  GI = `No, mi juego no usa la API de Steam Input`,
  KI = `Compatibilidad con control de Xbox`,
  qI = `Si tu juego ofrece compatibilidad total con controles de Xbox, los jugadores podrán iniciar, configurar, jugar y salir de tu juego sin necesidad de un teclado. Para poder indicar que es realmente compatible con controles de Xbox, tu juego tendrá que hacer lo siguiente:`,
  JI = `Los jugadores deben poder hacer todas las acciones necesarias en el juego con solo un control, como utilizar el lanzador previo o los menús, jugar, cambiar opciones y salir del juego.`,
  YI = `Si el control se desconecta, el juego deberá pausarse a menos que sea un juego multijugador.`,
  XI = `Cualquier mensaje para ingresar texto deberá abrir un teclado virtual en la pantalla.`,
  ZI = `Si el juego tiene un modo multijugador local, el modo debe funcionar con varios controles.`,
  QI = `¿Cumple tu juego con los criterios anteriores de compatibilidad total con el control de Xbox?`,
  $I = `Compat. con el control de Playstation`,
  eL = `Si tu juego es compatible con uno o más de los modelos de controles de PlayStation listados a continuación, por lo general debería ser posible usarlos para hacer en el juego todo lo que puede hacerse con los controles de Xbox. Además, tu juego debe hacer lo siguiente para ser considerado como compatible con controles de PlayStation:`,
  tL = `Mostrar los glifos (íconos) correctamente en la pantalla cuando se indique al usuario que presione un botón concreto del control.`,
  nL = `Jugar, interactuar con los menús, cambiar la configuración, salir del juego.`,
  rL = `<1>Nota acerca USB/Bluetooth:</1> Para controles de PlayStation en una PC, puede ser bastante común que la conexión USB funcione bien, pero que no tenga el mismo nivel de compatibilidad cuando se conecta mediante Bluetooth. Confirma con tu equipo técnico que el juego en realidad funciona mediante Bluetooth antes de seleccionar alguno que aparece a continuación.`,
  iL = `<1>Sí</1>, mi juego es compatible con: (selecciona todos los que correspondan)`,
  aL = `Integración de la API de Steam Input`,
  oL = `Si tu juego se ha integrado por completo con la API de Steam Input, entonces debería de funcionar por completo con cualquiera de los más de 200 modelos de controles que conecta un jugador, incluyendo modelos futuros. Para decir que tu juego cuenta verdaderamente con esta compatibilidad, necesitará por lo menos hacer estas cosas:`,
