  Cz = `Cuando lo tengas todo preparado para informar a los jugadores que has lanzado contenido en el Pase de temporada, utiliza la opción "Marcar como lanzado" que aparece a continuación y sigue las instrucciones. Consulta la <1>documentación sobre el lanzamiento de Pases de temporada</1> para obtener más información.`,
