  IB = `Hola %1$s:%2$s ¿Dónde te gustaría reunirte con nosotros?`,
  LB = `A continuación puedes ver una lista de eventos a los que se están planteando asistir miembros del equipo de Steam. Si tú también te lo estás planteando o si vives cerca y estarás disponible para reunirnos, usa el formulario que aparece a continuación para hacernos saber. Utilizaremos esta información para planificar mejor nuestros viajes y eventos. Daremos prioridad a quienes van a asistir a los eventos a los que tenemos previsto ir antes de enviar invitaciones adicionales.`,
