  iV = `Encuesta sobre Meet Steam: %1$s`,
  aV = `¿Tienes algún comentario sobre alguna de las sesiones de Steam a las que asististe en el espacio alquilado por Valve en Convene? Se trata literalmente de una encuesta de una sola pregunta. Solo queremos saber si hay algo que te haya llamado la atención sobre el contenido, la calidad, el horario, la ubicación o el tema de las sesiones, ya sea bueno o malo.`,
