  OV = `La salida final debe tener un volumen medio de -12 dB de pico y -14\xA0LUFS (Unidades de Sonoridad relativas a Fondo de Escala, por sus siglas en inglés). Normalizaremos el audio para asegurarnos de que no esté demasiado alto.`,
